mapper.select:
select wr.report_id, wr.household_id, wr.site_id, wr.user_id, wr.dong, wr.ho, wr.head_name, coalesce(hh.target_type, 'GENERAL') as target_type, date_format(wr.install_date, '%Y-%m-%d') as install_date, date_format(wr.report_time, '%Y-%m-%d %H:%i') as report_time, wr.reporter_name, wr.confirmer_name, wr.confirmer_signature, wr.photo_door, wr.photo_before1, wr.photo_after1, wr.photo_before2, wr.photo_after2, wr.`status`, wr.remarks, wr.fix_reason, wr.create_time, wr.last_update, s.name as site_name, s.sido, s.sigungu, s.eupmyeondong, s.address, s.region_id, coalesce(fr.name, s.region) as region, coalesce(fr.sido_name, s.sido) as region_sido from work_report wr left join site s on wr.site_id = s.site_id left join fire_region fr on s.region_id = fr.region_id left join household hh on ( (wr.household_id is not null and wr.household_id != '' and wr.household_id = hh.household_id) or ((wr.household_id is null or wr.household_id = '') and wr.site_id = hh.site_id and wr.dong = hh.dong and wr.ho = hh.ho) ) where wr.delete_flg = 0
and s.region_id = #{regionId}
and wr.status = #{status}
and wr.remarks is not null and trim(wr.remarks) != '' and wr.remarks not like '%특이사항 없음%'
and wr.install_date >= #{installStartDate}
and wr.install_date <= #{installEndDate}
and wr.report_time >= concat(#{reportStartDate}, ' 00:00:00')
and wr.report_time <= concat(#{reportEndDate}, ' 23:59:59')
and ( s.name like concat('%', #{query}, '%') or wr.dong like concat('%', #{query}, '%') or concat(wr.dong, '동') like concat('%', #{query}, '%') or wr.ho like concat('%', #{query}, '%') or concat(wr.ho, '호') like concat('%', #{query}, '%') or wr.reporter_name like concat('%', #{query}, '%') or wr.head_name like concat('%', #{query}, '%') )
and wr.user_id = #{userId}
and ( wr.user_id = #{portalUserId}
or s.region_id in
#{item}
)
and wr.site_id = #{siteId}
order by wr.report_time desc, wr.create_time desc
order by wr.report_time desc, wr.create_time desc
limit #{size} offset #{offset}
limit #{limit}

select count(*)
from work_report wr
left join site s on wr.site_id = s.site_id
where wr.delete_flg = 0

  and s.region_id = #{regionId}


  and wr.status = #{status}


  and wr.remarks is not null and trim(wr.remarks) != '' and wr.remarks not like '%특이사항 없음%'


  and wr.install_date >= #{installStartDate}


  and wr.install_date <= #{installEndDate}


  and wr.report_time >= concat(#{reportStartDate}, ' 00:00:00')


  and wr.report_time <= concat(#{reportEndDate}, ' 23:59:59')


  and (
    s.name like concat('%', #{query}, '%')
    or wr.dong like concat('%', #{query}, '%')
    or concat(wr.dong, '동') like concat('%', #{query}, '%')
    or wr.ho like concat('%', #{query}, '%')
    or concat(wr.ho, '호') like concat('%', #{query}, '%')
    or wr.reporter_name like concat('%', #{query}, '%')
    or wr.head_name like concat('%', #{query}, '%')
  )


  and wr.user_id = #{userId}


  and (
    wr.user_id = #{portalUserId}

      or s.region_id in

        #{item}


  )


  and wr.site_id = #{siteId}

select t.user_id as userId, t.name, t.phone, t.profile_img as profileImg, coalesce(sum(case when wr.report_id is not null then 1 else 0 end), 0) as total, coalesce(sum(case when wr.status = 'COMPLETED' then 1 else 0 end), 0) as completed, coalesce(sum(case when wr.status = 'PENDING' then 1 else 0 end), 0) as pending, coalesce(sum(case when wr.status = 'REJECTED' then 1 else 0 end), 0) as rejected from ( select distinct u.user_id, u.user_name as name, u.phone_num as phone, u.profile_img from user u inner join user_assigned_region uar on u.user_id = uar.user_id inner join fire_region fr on uar.region_id = fr.region_id where u.delete_flg = 0 and u.role_id = 1
and fr.region_id = #{regionId}
union select distinct u.user_id, u.user_name as name, u.phone_num as phone, u.profile_img from user u inner join work_report wr on u.user_id = wr.user_id and wr.delete_flg = 0 inner join site s on wr.site_id = s.site_id where u.delete_flg = 0 and u.role_id = 1
and s.region_id = #{regionId}
) t left join ( select wr_inner.user_id, wr_inner.report_id, wr_inner.status from work_report wr_inner left join site s_inner on wr_inner.site_id = s_inner.site_id where wr_inner.delete_flg = 0
and s_inner.region_id = #{regionId}
) wr on t.user_id = wr.user_id group by t.user_id, t.name, t.phone, t.profile_img order by total desc, completed desc, t.name asc
limit #{limit}

select count(*) from ( select distinct u.user_id from user u inner join user_assigned_region uar on u.user_id = uar.user_id inner join fire_region fr on uar.region_id = fr.region_id where u.delete_flg = 0 and u.role_id = 1
and fr.region_id = #{regionId}
union select distinct u.user_id from user u inner join work_report wr on u.user_id = wr.user_id and wr.delete_flg = 0 inner join site s on wr.site_id = s.site_id where u.delete_flg = 0 and u.role_id = 1
and s.region_id = #{regionId}
) t

select count(*) as totalReports, count(case when date(wr.install_date) = curdate() or date(wr.report_time) = curdate() then 1 end) as todayReports, count(case when wr.status = 'PENDING' then 1 end) as pendingReports, count(case when wr.status = 'REJECTED' then 1 end) as rejectedReports, count(case when wr.status = 'COMPLETED' then 1 end) as completedReports, count(case when wr.status = 'PENDING' and wr.remarks is not null and trim(wr.remarks) != '' and wr.remarks not like '%특이사항 없음%' then 1 end) as issueReportsCount from work_report wr left join site s on wr.site_id = s.site_id where wr.delete_flg = 0
and s.region_id = #{regionId}
and wr.user_id = #{userId}
